target.css:
:root {
  --ink: #172438;
  --muted: #667386;
  --paper: #fffdf8;
  --navy: #183b63;
  --blue: #3675a8;
  --blue-soft: #e7f1f8;
  --gold: #d69c32;
  --gold-soft: #fff1ce;
  --line: #d7dee5;
  --green: #247a61;
  --green-soft: #dff3e9;
  --red: #a94b4b;
}

.clearance-card {
  width: 500px;
  box-sizing: border-box;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.case-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  color: var(--paper);
  background: var(--navy);
}

.identity {
  display: flex;
  align-items: center;
  gap: 10px;
}

.passport-mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--navy);
  background: var(--gold);
  border-radius: 10px 10px 3px 10px;
  font-size: 19px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--blue-soft);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.case-header h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  color: var(--green);
  background: var(--green-soft);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.case-grid {
  display: grid;
  grid-template-columns: 118px 1fr;
  gap: 14px;
  padding: 14px 16px 12px;
}

.portrait {
  display: flex;
  min-height: 125px;
  box-sizing: border-box;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 0;
  background: var(--blue-soft);
  border: 1px solid var(--line);
  border-radius: 12px 12px 12px 3px;
}

.portrait-icon {
  display: grid;
  width: 47px;
  height: 47px;
  place-items: center;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 50%;
  font-size: 23px;
}

.portrait figcaption {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.review-panel {
  min-width: 0;
}

.review-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}

.review-title {
  margin: 0;
  font-size: 16px;
  font-weight: 800;
  line-height: 1;
}

.document-tag {
  padding: 4px 6px;
  color: var(--blue);
  background: var(--blue-soft);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.info-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px 16px;
  margin: 9px 0;
}

.info-list div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
}

.info-list dt {
  color: var(--muted);
  font-size: 10px;
}

.info-list dd {
  margin: 0;
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.route {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid var(--line);
}

.route-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.route-stops {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.route-stops li {
  padding: 3px 6px;
  color: var(--muted);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 10px;
  font-weight: 800;
}

.route-stops li.active {
  color: var(--navy);
  background: var(--gold-soft);
  border-color: var(--gold);
}

.case-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--blue-soft);
  border-top: 1px solid var(--line);
}

.case-footer p {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.1;
}

.case-footer strong {
  color: var(--ink);
  font-size: 11px;
}

.case-footer button {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--blue);
  border: 0;
  border-radius: 7px 7px 3px 7px;
  font-size: 11px;
  font-weight: 800;
}

